25|    public function units(UnitScopedRequest $request): JsonResponse
26|    {
27|        $accessibleIds = $request->accessibleIds();
28|        $scopeHash = md5(json_encode($accessibleIds));
29|
30|        $data = $this->cache->remember('report_units', $scopeHash, function () use ($accessibleIds) {
31|            // Single query: total + with_boundary via conditional aggregation (was 2 count queries)
32|            $stats = Unit::whereIn('id', $accessibleIds)
33|                ->selectRaw('COUNT(*) as total, SUM(CASE WHEN boundary_id IS NOT NULL THEN 1 ELSE 0 END) as with_boundary')
34|                ->first();
