36|            $total = (int) $stats->total;
37|            $withBoundary = (int) $stats->with_boundary;
38|            $withoutBoundary = $total - $withBoundary;
39|
40|            $byType = Unit::query()
41|                ->selectRaw('COALESCE(unit_types.name, ?) as type_name, COUNT(units.id) as count', ['نامشخص'])
42|                ->leftJoin('unit_types', 'units.unit_type_id', '=', 'unit_types.id')
43|                ->whereIn('units.id', $accessibleIds)
44|                ->groupBy('type_name')
45|                ->pluck('count', 'type_name')
46|                ->toArray();
47|
48|            return [
49|                'total' => $total,
50|                'with_boundary' => $withBoundary,
51|                'without_boundary' => $withoutBoundary,
52|                'by_type' => $byType,
53|            ];
54|        }, 10);
55|
56|        return response()->json($data);
57|    }
58|
59|    public function todos(UnitScopedRequest $request): JsonResponse
60|    {
61|        $days = $this->days($request);
62|        $accessibleIds = $request->accessibleIds();
63|        $scopeHash = md5(json_encode($accessibleIds));
64|
65|        $data = $this->cache->remember('report_todos', $scopeHash, function () use ($accessibleIds, $days) {
66|            $now = now();
67|            $query = Todo::whereIn('unit_id', $accessibleIds);
68|
69|            // Single query: completed/pending/overdue via conditional aggregation (was 3 count queries)
70|            $stats = (clone $query)
71|                ->selectRaw(
72|                    'SUM(CASE WHEN is_completed THEN 1 ELSE 0 END) as completed, '
73|                    .'SUM(CASE WHEN NOT is_completed THEN 1 ELSE 0 END) as pending, '
74|                    .'SUM(CASE WHEN NOT is_completed AND end_at IS NOT NULL AND end_at < ? THEN 1 ELSE 0 END) as overdue',
75|                    [$now]
76|                )
77|                ->first();
78|
79|            $byDay = $this->dailySeries($days, $query, 'start_at');
80|
81|            $byUnit = Todo::selectRaw('COALESCE(units.name, ?) as unit_name, COUNT(*) as count', ['نامشخص'])
82|                ->whereIn('todos.unit_id', $accessibleIds)
83|                ->leftJoin('units', 'todos.unit_id', '=', 'units.id')
84|                ->groupBy('unit_name')
85|                ->pluck('count', 'unit_name')
86|                ->toArray();
87|
88|            return [
89|                'completed' => (int) $stats->completed,
90|                'pending' => (int) $stats->pending,
91|                'overdue' => (int) $stats->overdue,
92|                'by_day' => $byDay,
93|                'by_unit' => $byUnit,
94|            ];
95|        }, 10, ['days' => $days]);
96|
97|        return response()->json($data);
98|    }
