100|    public function tickets(UnitScopedRequest $request): JsonResponse
101|    {
102|        $days = $this->days($request);
103|        $accessibleIds = $request->accessibleIds();
104|        $scopeHash = md5(json_encode($accessibleIds));
105|
106|        $data = $this->cache->remember('report_tickets', $scopeHash, function () use ($accessibleIds, $days) {
107|            $query = Ticket::whereIn('unit_id', $accessibleIds);
108|
109|            $byStatus = (clone $query)
110|                ->selectRaw('status, count(*) as count')
111|                ->groupBy('status')
112|                ->pluck('count', 'status')
113|                ->toArray();
114|
115|            $byPriority = (clone $query)
116|                ->selectRaw('priority, count(*) as count')
117|                ->groupBy('priority')
118|                ->pluck('count', 'priority')
119|                ->toArray();
120|
121|            $byDay = $this->dailySeries($days, $query, 'created_at');
122|
123|            return [
124|                'total' => array_sum($byStatus),
125|                'by_status' => $byStatus,
126|                'by_priority' => $byPriority,
127|                'by_day' => $byDay,
128|            ];
129|        }, 10, ['days' => $days]);
130|
131|        return response()->json($data);
132|    }
133|
134|    /**
135|     * Resolve and validate the `?days=` window (default 30, cap 365).
136|     *
137|     * The UI and the API used to disagree about what a daily chart covered —
138|     * the UI clipped to 30 while the API aggregated the whole history — so both
139|     * now take the window from here.
140|     */
141|    private function days(UnitScopedRequest $request): int
142|    {
143|        $request->validate(['days' => ['sometimes', new ReportDays]]);
144|
145|        return DailySeries::resolveDays($request->query('days'));
146|    }
147|
148|    /**
149|     * Daily counts as Jalali labels, one entry per day in the window.
150|     *
151|     * @param  EloquentBuilder<covariant Model>  $query  Already scoped to the caller's units
152|     * @return array<int, array{day: string, count: int}>
153|     */
154|    private function dailySeries(int $days, EloquentBuilder $query, string $dateColumn): array
155|    {
