35|            'type' => 'nullable|string|max:50',
36|            'os' => 'nullable|string|max:100',
37|            'ip_valid' => 'nullable|string|max:45',
38|            'ip_local' => 'nullable|string|max:45',
39|            'mac' => 'nullable|string|max:17',
40|            'net_type' => 'nullable|string|max:50',
41|            'switch' => 'nullable|string|max:100',
42|            'port' => 'nullable|string|max:50',
