116|        $query = Hardware::join('persons', 'hardwares.n_code', '=', 'persons.n_code')
117|            ->whereIn('persons.u_id', $accessibleIds)
118|            ->select('hardwares.*')
119|            ->distinct();
120|
121|        // Apply query scopes for filters
122|        $query->filterSearch($request->input('search'))
123|            ->filterType($request->input('type'))
124|            ->filterOs($request->input('os'))
125|            ->filterCpu($request->input('cpu'))
