240|    public function stats(UnitScopedRequest $request): JsonResponse
241|    {
242|        $accessibleIds = $request->accessibleIds();
243|
244|        // Issue #217: cache stats to avoid 3 heavy queries per request.
245|        // Key is scoped by (version, accessible units): the version counter is
246|        // bumped on every hardware write (Hardware::flushStatsCache()), which
247|        // invalidates all previously cached scopes without flushing the whole
248|        // cache. Stale entries expire naturally via the 10-minute TTL.
249|        $version = Cache::get('hardware_stats_version', 0);
