251|
252|        $data = Cache::remember($cacheKey, now()->addMinutes(10), function () use ($accessibleIds) {
253|            $baseQuery = Hardware::join('persons', 'hardwares.n_code', '=', 'persons.n_code')
254|                ->whereIn('persons.u_id', $accessibleIds)
255|                ->select('hardwares.*');
256|
257|            return [
258|                'total' => $baseQuery->count(),
259|                'by_type' => (clone $baseQuery)->select('type', DB::raw('count(*) as count'))
260|                    ->groupBy('type')
261|                    ->pluck('count', 'type')
262|                    ->toArray(),
263|                'shutdown' => (clone $baseQuery)->where('shutdown', true)->count(),
264|            ];
265|        });
266|
267|        return response()->json([
268|            'success' => true,
269|            'data' => $data,
270|        ]);
