315|            }
316|        }
317|
318|        // Only allow http, https, mailto, tel
319|        if (! preg_match('/^(https?|mailto|tel):/i', $url)) {
320|            return '#';
321|        }
322|
323|        // Escape any remaining dangerous chars in the URL value (e.g., spaces, quotes, angle brackets)
324|        return htmlspecialchars($url, ENT_QUOTES | ENT_HTML5, 'UTF-8');
