3|namespace App\Http\Controllers\Api;
4|
5|use App\Http\Controllers\Controller;
6|use App\Http\Requests\UnitScopedRequest;
7|use App\Models\Hardware;
8|use App\Models\Ticket;
9|use App\Models\Unit;
10|use App\Services\CacheInvalidationServiceInterface;
11|use App\Traits\PersianNormalizer;
12|use Illuminate\Http\JsonResponse;
13|use Illuminate\Support\Facades\Cache;
14|
15|class GisController extends Controller
16|{
17|    use PersianNormalizer;
18|
19|    public function __construct(
20|        protected CacheInvalidationServiceInterface $cache
21|    ) {}
22|
23|    /**
24|     * Apply bbox spatial filter using lat/lng columns (works without geom column).
25|     */
26|    protected function applyBbox($query, UnitScopedRequest $request)
27|    {
28|        if (! $request->filled('bbox')) {
29|            return $query;
30|        }
31|
32|        $bbox = explode(',', $request->bbox);
33|        if (count($bbox) !== 4) {
34|            return $query;
35|        }
36|
37|        [$minLon, $minLat, $maxLon, $maxLat] = array_map('floatval', $bbox);
38|
39|        $query->whereBetween('lat', [$minLat, $maxLat])
40|            ->whereBetween('lng', [$minLon, $maxLon]);
41|
42|        return $query;
43|    }
44|
45|    /**
46|     * Bbox filter for queries with prefixed/aliased columns (JOINs) — Issue #404.
47|     */
48|    protected function applyBboxAliased($query, UnitScopedRequest $request)
49|    {
50|        if (! $request->filled('bbox')) {
51|            return $query;
52|        }
53|
54|        $bbox = explode(',', $request->bbox);
55|        if (count($bbox) !== 4) {
56|            return $query;
57|        }
58|
59|        [$minLon, $minLat, $maxLon, $maxLat] = array_map('floatval', $bbox);
60|
61|        $query->whereBetween('units.lat', [$minLat, $maxLat])
62|            ->whereBetween('units.lng', [$minLon, $maxLon]);
63|
64|        return $query;
65|    }
66|
67|    /**
68|     * Build a normalized bbox string for cache keys (4 decimal places ≈ 11m precision).
69|     * Fixes Issue #456: GIS bbox rounding caused incorrect map data display.
70|     */
71|    protected function normalizedBbox(UnitScopedRequest $request): string
72|    {
73|        if (! $request->filled('bbox')) {
74|            return 'all';
75|        }
76|
77|        $bbox = explode(',', $request->bbox);
78|        if (count($bbox) !== 4) {
79|            return 'all';
80|        }
81|
82|        [$minLon, $minLat, $maxLon, $maxLat] = array_map('floatval', $bbox);
83|
84|        return implode(',', [
85|            round($minLon, 4),
86|            round($minLat, 4),
87|            round($maxLon, 4),
88|            round($maxLat, 4),
89|        ]);
90|    }
91|
92|    /**
93|     * Build a cache key for GIS endpoints via the unified service.
94|     * Uses the shared 'gis' namespace (incremented on hardware/person changes)
95|     * and includes the endpoint in extra data for per-endpoint separation.
96|     * Sorts accessibleIds to ensure consistent cache keys regardless of DB result order.
97|     */
98|    protected function gisCacheKey(string $endpoint, array $accessibleIds, string $bbox, array $extra = []): string
99|    {
100|        $idStrings = array_map('strval', $accessibleIds);
101|        sort($idStrings, SORT_STRING);
102|        $scopeHash = md5(implode(',', $idStrings));
103|        $extra = array_merge(['endpoint' => $endpoint], $extra);
104|        $extraHash = md5(serialize($extra));
105|
106|        return $this->cache->cacheKey('gis', $scopeHash, "{$bbox}:{$extraHash}");
107|    }
108|
109|    /**
110|     * Get units as GeoJSON FeatureCollection within spatial bounds.
