281|    protected function transformAudit(HardwareAudit $audit, bool $withFullDiff = false): array
282|    {
283|        $data = [
284|            'id' => $audit->id,
285|            'action' => $audit->action,
286|            'action_label' => $this->getActionLabel($audit->action),
287|            'source' => $audit->source,
288|            'source_label' => $this->getSourceLabel($audit->source),
289|            'changes' => $audit->changes,
290|            'ip_address' => $audit->ip_address,
291|            'user_agent' => $audit->user_agent,
292|            'created_at' => $audit->created_at?->toIso8601String(),
293|            'created_at_jalali' => $audit->created_at
294|                ? Jalalian::fromCarbon($audit->created_at)->format('Y/m/d H:i:s')
295|                : null,
296|            'user' => $audit->user ? [
297|                'id' => $audit->user->id,
298|                'n_code' => $audit->user->n_code,
299|                'name' => $audit->user->name,
300|            ] : null,
301|        ];
302|
303|        if ($withFullDiff && $audit->changes) {
304|            $data['diff_summary'] = $this->buildDiffSummary($audit->changes);
305|        }
306|
307|        return $data;
308|    }
309|
310|    /**
311|     * Get Persian label for action.
312|     */
313|    protected function getActionLabel(string $action): string
314|    {
315|        return match ($action) {
316|            'created' => 'ایجاد',
317|            'updated' => 'بروزرسانی',
318|            'deleted' => 'حذف',
319|            'bulk_mark' => 'علامت‌گذاری گروهی',
320|            'bulk_delete' => 'حذف گروهی',
321|            'force_deleted' => 'حذف اجباری',
322|            'rollback' => 'بازگردانی',
323|            default => $action,
324|        };
325|    }
326|
327|    /**
328|     * Get Persian label for source.
329|     */
330|    protected function getSourceLabel(string $source): string
331|    {
332|        return match ($source) {
333|            'web' => 'وب',
334|            'api' => 'API (موبایل)',
335|            'import' => 'ایمپورت',
336|            'bulk' => 'عملیات گروهی',
337|            default => $source,
338|        };
339|    }
340|
341|    /**
342|     * Build human-readable diff summary.
343|     */
344|    protected function buildDiffSummary(array $changes): array
345|    {
346|        $summary = [];
347|        foreach ($changes as $change) {
348|            $summary[] = 'فیلد <strong>'.e($change['field'])."</strong>: از <span class='text-error'>".e($change['old'])."</span> به <span class='text-success'>".e($change['new']).'</span> تغییر یافت.';
349|        }
350|
351|        return $summary;
352|    }
353|
354|    /**
355|     * Parse value for restore (reverse of formatValueForDisplay).
356|     */
357|    protected function parseValueForRestore(string $displayValue, string $field): mixed
358|    {
359|        if ($displayValue === '—') {
360|            return null;
361|        }
362|        if ($displayValue === 'بله') {
363|            return true;
364|        }
365|        if ($displayValue === 'خیر') {
366|            return false;
367|        }
368|
369|        // Try to parse as JSON for arrays
370|        if (str_starts_with($displayValue, '[') || str_starts_with($displayValue, '{')) {
371|            $decoded = json_decode($displayValue, true);
372|            if (json_last_error() === JSON_ERROR_NONE) {
373|                return $decoded;
374|            }
375|        }
376|
377|        // Handle numeric fields
378|        $numericFields = ['ram', 'vlan', 'port'];
379|        if (in_array($field, $numericFields, true) && is_numeric($displayValue)) {
380|            return (int) $displayValue;
381|        }
382|
383|        return $displayValue;
384|    }
