133|                     WHERE p.u_id = ANY(?) AND p.s_id IS NOT NULL
134|                     GROUP BY s.name",
135|                    [$idArray, $idArray]
136|                );
137|
138|                $byUnitType = [];
139|                $bySemat = [];
140|                foreach ($rows as $row) {
