4|
5|use App\Http\Controllers\Controller;
6|use App\Http\Requests\UnitScopedRequest;
7|use App\Models\Unit;
8|use App\Services\CacheInvalidationServiceInterface;
9|use Illuminate\Http\JsonResponse;
10|use Illuminate\Support\Facades\Cache;
11|
12|/**
13| * Org-chart tree endpoints — extracted from HrController.
14| */
15|class OrgChartController extends Controller
16|{
17|    /**
18|     * GET /api/hr/org-chart — full org tree with personnel counts per unit.
19|     */
20|    public function orgChart(UnitScopedRequest $request): JsonResponse
21|    {
22|        $accessibleIds = $request->accessibleIds();
23|
24|        $data = Cache::remember(
25|            $this->hrStatsCacheKey($accessibleIds, 'orgchart'),
26|            now()->addMinutes(10),
27|            function () use ($accessibleIds) {
28|                $units = Unit::whereIn('id', $accessibleIds)
29|                    ->withCount(['person as personnel_count'])
30|                    ->get();
31|
32|                // Build nested tree from flat list (parent_id references).
33|                // The else-branch below is the same predicate UnitTreeService::roots()
34|                // applies (parent is null, or the parent is out of scope) — see
35|                // issue #704. It stays inline here deliberately: the loop already
36|                // holds every accessible unit in $byId, so calling roots() would
37|                // re-query the same rows to learn something this loop can read off
38|                // directly. The Livewire `unit.tree` component, which does NOT
39|                // already have the flat list in hand, uses the service.
40|                $byId = $units->keyBy('id');
41|                $tree = [];
42|                foreach ($units as $unit) {
43|                    if ($unit->parent_id && $byId->has($unit->parent_id)) {
44|                        $byId[$unit->parent_id]->children ??= [];
45|                        $byId[$unit->parent_id]->children[] = $unit;
46|                    } else {
47|                        $tree[] = $unit;
48|                    }
49|                }
50|
51|                $format = function ($unit) use (&$format) {
52|                    return [
53|                        'id' => $unit->id,
54|                        'name' => $unit->name,
55|                        'parent_id' => $unit->parent_id,
56|                        'personnel_count' => $unit->personnel_count,
57|                        'children' => isset($unit->children)
58|                            ? collect($unit->children)->map($format)->values()
59|                            : [],
60|                    ];
61|                };
62|
63|                return collect($tree)->map($format)->values();
